"""Immutable semantic contract between compilers and native kernel providers.

This module deliberately knows nothing about torch, CuTe, model names, or AOT
bundle layout.  A compiler describes required computation as a
``KernelDemand``; provider-owned resolvers either return a candidate
``NativeResolution`` or a structured ``Rejection``.  The compiler can then
price all candidates without rediscovering provider legality.

Artifact and wheel-manifest binding is a later boundary.  ``implementation``
identifies a provider's logical implementation here, not a packaged cubin.
"""

from __future__ import annotations

import enum
from dataclasses import dataclass, field
from typing import Mapping, Protocol, Sequence, TypeAlias, runtime_checkable

from kestrel_kernels.arch import parse_torch_arch_list_entry


FrozenValue: TypeAlias = None | bool | int | float | str | tuple["FrozenValue", ...]
FrozenItems: TypeAlias = tuple[tuple[str, FrozenValue], ...]
_DTYPE_ALIASES = {
    "bfloat16": "bf16",
    "float16": "fp16",
    "float32": "fp32",
    "float8_e4m3fn": "fp8_e4m3",
    "float8_e5m2": "fp8_e5m2",
}


def _token(value, *, field_name: str) -> str:
    raw = value.value if isinstance(value, enum.Enum) else value
    token = str(raw)
    if not token:
        raise ValueError(f"{field_name} must be non-empty")
    return token


def _dtype_token(value, *, field_name: str) -> str:
    token = _token(value, field_name=field_name)
    if token.startswith("torch."):
        token = token[len("torch."):]
    return _DTYPE_ALIASES.get(token, token)


def _field_name(value, *, kind: str) -> str:
    if not isinstance(value, str) or not value:
        raise TypeError(f"{kind} names must be non-empty strings")
    return value


def _freeze_value(value) -> FrozenValue:
    if isinstance(value, enum.Enum):
        return _freeze_value(value.value)
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, Mapping):
        return _freeze_items(value)
    if isinstance(value, (list, tuple)):
        return tuple(_freeze_value(item) for item in value)
    if isinstance(value, (set, frozenset)):
        frozen = tuple(_freeze_value(item) for item in value)
        return tuple(sorted(frozen, key=repr))
    raise TypeError(
        "native coverage values must be scalars, enums, mappings, or sequences; "
        f"got {type(value).__name__}"
    )


def _freeze_items(values) -> FrozenItems:
    items = values.items() if isinstance(values, Mapping) else values
    frozen = []
    seen = set()
    for raw_name, value in items:
        name = _field_name(raw_name, kind="native coverage field")
        if name in seen:
            raise ValueError(f"duplicate native coverage field {name!r}")
        seen.add(name)
        frozen.append((name, _freeze_value(value)))
    return tuple(sorted(frozen, key=lambda item: item[0]))


@dataclass(frozen=True)
class ExtentBound:
    """Inclusive runtime extent admitted by one compiled native resolution."""

    lower: int
    upper: int

    def __post_init__(self) -> None:
        if (
            isinstance(self.lower, bool)
            or isinstance(self.upper, bool)
            or not isinstance(self.lower, int)
            or not isinstance(self.upper, int)
        ):
            raise TypeError("extent bounds must be integers")
        if self.lower < 0 or self.upper < self.lower:
            raise ValueError(
                f"invalid extent bound [{self.lower}, {self.upper}]"
            )


def _freeze_bounds(values) -> tuple[tuple[str, ExtentBound], ...]:
    items = values.items() if isinstance(values, Mapping) else values
    frozen = []
    seen = set()
    for raw_name, raw_bound in items:
        name = _field_name(raw_name, kind="dynamic-bound")
        if name in seen:
            raise ValueError(f"duplicate dynamic bound {name!r}")
        seen.add(name)
        if isinstance(raw_bound, ExtentBound):
            bound = raw_bound
        else:
            try:
                lower, upper = raw_bound
            except (TypeError, ValueError) as exc:
                raise TypeError(
                    f"dynamic bound {name!r} must be ExtentBound or (lower, upper)"
                ) from exc
            bound = ExtentBound(lower, upper)
        frozen.append((name, bound))
    return tuple(sorted(frozen, key=lambda item: item[0]))


@dataclass(frozen=True)
class KernelDemand:
    """One model-agnostic semantic operation demand derived from compiler IR."""

    op_kind: str
    input_dtype: str
    storage_dtype: str | None = None
    layout: str | None = None
    dimensions: FrozenItems | Mapping[str, int] = field(default_factory=tuple)
    semantics: FrozenItems | Mapping[str, object] = field(default_factory=tuple)
    dynamic_bounds: (
        tuple[tuple[str, ExtentBound], ...]
        | Mapping[str, ExtentBound | tuple[int, int]]
    ) = field(default_factory=tuple)

    def __post_init__(self) -> None:
        object.__setattr__(self, "op_kind", _token(self.op_kind, field_name="op_kind"))
        object.__setattr__(
            self,
            "input_dtype",
            _dtype_token(self.input_dtype, field_name="input_dtype"),
        )
        if self.storage_dtype is not None:
            object.__setattr__(
                self,
                "storage_dtype",
                _dtype_token(self.storage_dtype, field_name="storage_dtype"),
            )
        if self.layout is not None:
            object.__setattr__(self, "layout", _token(self.layout, field_name="layout"))

        dimensions = _freeze_items(self.dimensions)
        for name, value in dimensions:
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise ValueError(
                    f"dimension {name!r} must be a non-negative integer, got {value!r}"
                )
        object.__setattr__(self, "dimensions", dimensions)
        object.__setattr__(self, "semantics", _freeze_items(self.semantics))
        object.__setattr__(self, "dynamic_bounds", _freeze_bounds(self.dynamic_bounds))

    def dimension(self, name: str) -> int:
        for field_name, value in self.dimensions:
            if field_name == name:
                return value
        raise KeyError(name)


@dataclass(frozen=True)
class NativeTarget:
    """Concrete code-generation target for which a provider is resolved.

    ``backend`` alone is insufficient to certify a compiled artifact: a native
    implementation available for one CUDA architecture may be absent or
    illegal on another.  Requiring both fields prevents an architecture-free
    resolution from satisfying compiler totality by construction.
    """

    backend: str
    arch: str

    def __post_init__(self) -> None:
        backend = _token(self.backend, field_name="backend").lower()
        arch = _token(self.arch, field_name="arch")
        if backend == "cuda":
            arch = parse_torch_arch_list_entry(arch) or arch.lower()
        object.__setattr__(self, "backend", backend)
        object.__setattr__(self, "arch", arch)


@dataclass(frozen=True)
class NativeResolution:
    """A provider candidate that can serve a semantic demand on one target."""

    provider: str
    implementation: str
    target: NativeTarget
    demand: KernelDemand
    constraints: FrozenItems | Mapping[str, object] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        if not isinstance(self.demand, KernelDemand):
            raise TypeError("native resolution demand must be a KernelDemand")
        if not isinstance(self.target, NativeTarget):
            raise TypeError("native resolution target must be a NativeTarget")
        object.__setattr__(self, "provider", _token(self.provider, field_name="provider"))
        object.__setattr__(
            self,
            "implementation",
            _token(self.implementation, field_name="implementation"),
        )
        object.__setattr__(self, "constraints", _freeze_items(self.constraints))


@dataclass(frozen=True)
class Rejection:
    """Structured reason a provider cannot serve a semantic demand."""

    provider: str
    target: NativeTarget
    demand: KernelDemand
    code: str
    reason: str
    details: FrozenItems | Mapping[str, object] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        if not isinstance(self.demand, KernelDemand):
            raise TypeError("rejection demand must be a KernelDemand")
        if not isinstance(self.target, NativeTarget):
            raise TypeError("rejection target must be a NativeTarget")
        object.__setattr__(self, "provider", _token(self.provider, field_name="provider"))
        object.__setattr__(self, "code", _token(self.code, field_name="code"))
        if not self.reason:
            raise ValueError("rejection reason must be non-empty")
        object.__setattr__(self, "details", _freeze_items(self.details))


ProviderResult: TypeAlias = NativeResolution | Rejection


@runtime_checkable
class NativeProvider(Protocol):
    """Provider-owned pure legality resolver."""

    name: str
    op_kinds: frozenset[str]

    def resolve(self, demand: KernelDemand, target: NativeTarget) -> ProviderResult:
        ...


class ProviderContractError(ValueError):
    """A provider returned a result inconsistent with its registry entry."""


@dataclass(frozen=True)
class NativeProviderRegistry:
    """Immutable, deterministic collection of native providers.

    ``evaluate`` returns every matching provider's result.  It intentionally
    does not choose a winner: provider selection belongs to compiler pricing.
    """

    providers: Sequence[NativeProvider] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        providers = tuple(sorted(tuple(self.providers), key=lambda provider: provider.name))
        names = [provider.name for provider in providers]
        duplicates = sorted({name for name in names if names.count(name) > 1})
        if duplicates:
            raise ValueError(f"duplicate native provider name(s): {duplicates}")
        for provider in providers:
            if not isinstance(provider.name, str) or not provider.name:
                raise ValueError("native provider name must be a non-empty string")
            if not isinstance(provider.op_kinds, frozenset):
                raise TypeError(
                    f"native provider {provider.name!r} op_kinds must be a frozenset"
                )
            if not provider.op_kinds:
                raise ValueError(
                    f"native provider {provider.name!r} must declare at least one op kind"
                )
            if any(not isinstance(op_kind, str) or not op_kind for op_kind in provider.op_kinds):
                raise ValueError(
                    f"native provider {provider.name!r} op kinds must be non-empty strings"
                )
        object.__setattr__(self, "providers", providers)

    def with_provider(self, provider: NativeProvider) -> "NativeProviderRegistry":
        return NativeProviderRegistry((*self.providers, provider))

    def evaluate(
        self,
        demand: KernelDemand,
        target: NativeTarget,
    ) -> tuple[ProviderResult, ...]:
        if not isinstance(target, NativeTarget):
            raise TypeError("native provider registry target must be a NativeTarget")
        matching = tuple(
            provider for provider in self.providers if demand.op_kind in provider.op_kinds
        )
        if not matching:
            return (
                Rejection(
                    provider="registry",
                    target=target,
                    demand=demand,
                    code="no_provider",
                    reason=f"no native provider declares op kind {demand.op_kind!r}",
                ),
            )

        results = []
        for provider in matching:
            result = provider.resolve(demand, target)
            if not isinstance(result, (NativeResolution, Rejection)):
                raise ProviderContractError(
                    f"native provider {provider.name!r} returned {type(result).__name__}; "
                    "expected NativeResolution or Rejection"
                )
            if result.provider != provider.name:
                raise ProviderContractError(
                    f"native provider {provider.name!r} returned provider={result.provider!r}"
                )
            if result.demand != demand or result.target != target:
                raise ProviderContractError(
                    f"native provider {provider.name!r} returned a result for a different "
                    "demand or target"
                )
            results.append(result)
        return tuple(results)

    def candidates(
        self,
        demand: KernelDemand,
        target: NativeTarget,
    ) -> tuple[NativeResolution, ...]:
        return tuple(
            result
            for result in self.evaluate(demand, target)
            if isinstance(result, NativeResolution)
        )


__all__ = [
    "ExtentBound",
    "KernelDemand",
    "NativeProvider",
    "NativeProviderRegistry",
    "NativeResolution",
    "NativeTarget",
    "ProviderContractError",
    "ProviderResult",
    "Rejection",
]
